      <div class="sgt-actions"><button type="button" class="sgt-btn primary" id="sgtTrendApply">APPLICA TREND A TUTTA LA REGIONE</button><button type="button" class="sgt-btn" id="sgtTrendCopy">COPIA DATI 2022</button><button type="button" class="sgt-btn" id="sgtTrendReset">RESET AI VALORI SONDAGGIO</button><button type="button" class="sgt-btn" id="sgtTrendWrite">SCRIVI REGIONE NEI SONDAGGI</button></div>
