  HOST.querySelectorAll("[data-sgt-value]").forEach(input=>input.addEventListener("change",()=>{S.manual[S.region]??={};S.manual[S.region][input.dataset.sgtValue]=clamp(input.value);save();render();}));
  document.getElementById("sgtTrendApply").onclick=()=>{const ps2=getParties();S.manual[S.region]??={};Object.keys(ps2).forEach(id=>S.manual[S.region][id]=scenarioValue(S.chamber,S.region,id));save();render();};
  document.getElementById("sgtTrendCopy").onclick=()=>{const ps2=getParties();S.manual[S.region]??={};Object.keys(ps2).forEach(id=>{const v=historical(S.chamber,2022,S.region,id);if(v!=null)S.manual[S.region][id]=v;});save();render();};
  document.getElementById("sgtTrendReset").onclick=()=>{const ps2=getParties();S.manual[S.region]??={};Object.keys(ps2).forEach(id=>S.manual[S.region][id]=defaultValue(S.chamber,S.region,id));save();render();};
